import{_ as a,o as r,c as t,a3 as i}from"./chunks/framework.DFRwgAh-.js";const _=JSON.parse('{"title":"エンタープライズセキュリティ・オンプレミス","description":"金融・エンタープライズ向けの閉域網（Air-Gapped）オンプレミス配備、社内ローカルLLM/Visionモデル連携、個人情報（PII）マスキング解説。","frontmatter":{"title":"エンタープライズセキュリティ・オンプレミス","description":"金融・エンタープライズ向けの閉域網（Air-Gapped）オンプレミス配備、社内ローカルLLM/Visionモデル連携、個人情報（PII）マスキング解説。","sort":1100,"head":[["link",{"rel":"canonical","href":"https://empasy.io/docs/ja/synceta/enterprise-security.html"}]]},"headers":[],"relativePath":"ja/synceta/enterprise-security.md","filePath":"ja/synceta/enterprise-security.md","lastUpdated":1787636174000}'),n={name:"ja/synceta/enterprise-security.md"};function s(l,e,o,c,d,p){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="エンタープライズセキュリティ・オンプレミス" tabindex="-1">エンタープライズセキュリティ・オンプレミス <a class="header-anchor" href="#エンタープライズセキュリティ・オンプレミス" aria-label="Permalink to “エンタープライズセキュリティ・オンプレミス”">​</a></h1><p>SyncETAは、金融・公共分野の厳格なセキュリティ基準を満たす<strong>完全なオンプレミス閉域網（Air-Gapped）配備</strong>を提供します。</p><hr><h2 id="_1-閉域網アーキテクチャ" tabindex="-1">1. 閉域網アーキテクチャ <a class="header-anchor" href="#_1-閉域網アーキテクチャ" aria-label="Permalink to “1. 閉域網アーキテクチャ”">​</a></h2><p>外部インターネット接続が遮断された環境でも、ローカルGPU基盤（vLLM、Ollama）と連携して独立稼働します。</p><ul><li><strong>オープンウェイトモデル対応</strong>: Qwen2-VL、LLaVAなどを社内環境で稼働。</li><li><strong>OpenAI互換API連携</strong>: エンドポイントURL設定のみで社内モデルへ切り替え可能。</li></ul><hr><h2 id="_2-個人情報マスキング-pii-masking" tabindex="-1">2. 個人情報マスキング（PII Masking） <a class="header-anchor" href="#_2-個人情報マスキング-pii-masking" aria-label="Permalink to “2. 個人情報マスキング（PII Masking）”">​</a></h2><ul><li><strong>DOMレベル暗号化</strong>: パスワード項目や正規表現に一致する個人情報を <code>********</code> に即座にマスキング。</li><li><strong>視覚的ブラー処理</strong>: 画面キャプチャおよび録画ビデオ保存時に特定要素エリアをぼかし処理。</li></ul><hr><h2 id="_3-rbac権限・監査ログ" tabindex="-1">3. RBAC権限・監査ログ <a class="header-anchor" href="#_3-rbac権限・監査ログ" aria-label="Permalink to “3. RBAC権限・監査ログ”">​</a></h2><ul><li><strong>ロール別アクセス制御</strong>: システム管理者、プロジェクトリーダー、QAエンジニア、テスターの権限分離。</li><li><strong>監査ログの永続化</strong>: セレクター自己修復の承認履歴やテスト実行記録を保存。</li></ul>',12)])])}const g=a(n,[["render",s]]);export{_ as __pageData,g as default};
